-- Applied to prod 2026-10-14; file landed for ledger parity (no re-apply needed).
do $$ declare r record; n text; begin for r in select c.conrelid::regclass as tbl, cl.relname, c.conname, c.conkey, (select string_agg(quote_ident(a.attname), ', ' order by k.ord) from unnest(c.conkey) with ordinality k(attnum,ord) join pg_attribute a on a.attrelid=c.conrelid and a.attnum=k.attnum) cols from pg_constraint c join pg_class cl on cl.oid=c.conrelid join pg_namespace ns on ns.oid=cl.relnamespace where c.contype='f' and ns.nspname='public' and cl.relkind='r' and not exists (select 1 from pg_index i where i.indrelid=c.conrelid and (i.indkey::int2[])[0:array_length(c.conkey,1)-1] operator(pg_catalog.@>) c.conkey and (i.indkey::int2[])[0:array_length(c.conkey,1)-1] operator(pg_catalog.<@) c.conkey) loop n := left('idx_fk_'||r.relname||'_'||md5(r.conname), 63); execute format('create index if not exists %I on %s (%s)', n, r.tbl, r.cols); end loop; end $$;
